11	    static ConnectedComponent traverse(
12	            Graph graph,
13	            Vertex startVertex,
14	            VisitedVertices visited) {
15	        Queue<Vertex> pendingVertices = new ArrayDeque<>();
16	        List<Vertex> componentVertices = new ArrayList<>();
17	
18	        visited.markVisited(startVertex);
19	        pendingVertices.add(startVertex);
20	
21	        while (!pendingVertices.isEmpty()) {
22	            Vertex currentVertex = pendingVertices.remove();
23	            componentVertices.add(currentVertex);
24	
25	            for (Vertex neighbor : graph.neighborsOf(currentVertex)) {
26	                if (visited.markVisitedIfUnvisited(neighbor)) {
27	                    pendingVertices.add(neighbor);
28	                }
29	            }
30	        }
31	
32	        return new ConnectedComponent(componentVertices);
33	    }
